for (const [a, b] of Object.entries({"centrecommercial": "luxe", "boutique": "luxe", "pipeline": "beaute", "mine": "acier", "ui:cpu": "semi", "ui:car": "auto", "ui:bag": "luxe", "ui:box": "ciment", "ui:bolt": "electricite", "ui:leaf": "feuille", "ui:chercher": "recherche", "ui:flamme": "gaz", "ui:goutte": "beaute", "ui:diamant": "casino", "ui:barres": "indice"})) traces[a] = traces[b];

/** Une icône en SVG ; `nom` : un secteur (« semi ») ou « ui:chercher ». */
export const icone = (nom, taille = 16) =>
  `<svg width="${taille}" height="${taille}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" style="flex:none">${traces[nom] ?? traces["ui:defaut"]}</svg>`;
